   456  struct OpenTypeFontFile
   457  {
   458    enum {
   459      CFFTag              = HB_TAG ('O','T','T','O'), /* OpenType with Postscript outlines */
   460      TrueTypeTag         = HB_TAG ( 0 , 1 , 0 , 0 ), /* OpenType with TrueType outlines */
   461      TTCTag              = HB_TAG ('t','t','c','f'), /* TrueType Collection */
   462      DFontTag            = HB_TAG ( 0 , 0 , 1 , 0 ), /* DFont Mac Resource Fork */
   463      TrueTag             = HB_TAG ('t','r','u','e'), /* Obsolete Apple TrueType */
   464      Typ1Tag             = HB_TAG ('t','y','p','1')  /* Obsolete Apple Type1 font in SFNT container */
   465    };
   466
   467    inline hb_tag_t get_tag (void) const { return u.tag; }
   468
   469    inline unsigned int get_face_count (void) const
   470    {
   471      switch (u.tag) {
   472      case CFFTag:        /* All the non-collection tags */
   473      case TrueTag:
   474      case Typ1Tag:
   475      case TrueTypeTag:   return 1;
   476      case TTCTag:        return u.ttcHeader.get_face_count ();
   477      case DFontTag:      return u.rfHeader.get_face_count ();
   478      default:            return 0;
   479      }
   480    }
   481    inline const OpenTypeFontFace& get_face (unsigned int i, unsigned int *base_offset = nullptr) const
   482    {
   483      if (base_offset)
   484        *base_offset = 0;
   485      switch (u.tag) {
   486      /* Note: for non-collection SFNT data we ignore index.  This is because
   487       * Apple dfont container is a container of SFNT's.  So each SFNT is a
   488       * non-TTC, but the index is more than zero. */
   489      case CFFTag:        /* All the non-collection tags */
   490      case TrueTag:
   491      case Typ1Tag:
   492      case TrueTypeTag:   return u.fontFace;
   493      case TTCTag:        return u.ttcHeader.get_face (i);
   494      case DFontTag:      return u.rfHeader.get_face (i, base_offset);
   495      default:            return Null(OpenTypeFontFace);
   496      }
   497    }
