   499    inline bool serialize_single (hb_serialize_context_t *c,
   500                                  hb_tag_t sfnt_tag,
   501                                  Supplier<hb_tag_t> &tags,
   502                                  Supplier<hb_blob_t *> &blobs,
   503                                  unsigned int table_count)
   504    {
   505      TRACE_SERIALIZE (this);
   506      assert (sfnt_tag != TTCTag);
   507      if (unlikely (!c->extend_min (*this))) return_trace (false);
   508      return_trace (u.fontFace.serialize (c, sfnt_tag, tags, blobs, table_count));
   509    }
   510
   511    inline bool sanitize (hb_sanitize_context_t *c) const
   512    {
   513      TRACE_SANITIZE (this);
   514      if (unlikely (!u.tag.sanitize (c))) return_trace (false);
   515      switch (u.tag) {
   516      case CFFTag:        /* All the non-collection tags */
   517      case TrueTag:
   518      case Typ1Tag:
   519      case TrueTypeTag:   return_trace (u.fontFace.sanitize (c));
   520      case TTCTag:        return_trace (u.ttcHeader.sanitize (c));
   521      case DFontTag:      return_trace (u.rfHeader.sanitize (c));
   522      default:            return_trace (true);
   523      }
   524    }
