   567  /* An array starting at second element. */
   568  template <typename Type, typename LenType=HBUINT16>
   569  struct HeadlessArrayOf
   570  {
   571    inline const Type& operator [] (unsigned int i) const
   572    {
   573      if (unlikely (i >= lenP1 || !i)) return Null(Type);
   574      return arrayZ[i-1];
   575    }
   576    inline Type& operator [] (unsigned int i)
   577    {
   578      if (unlikely (i >= lenP1 || !i)) return Crap(Type);
   579      return arrayZ[i-1];
   580    }
   581    inline unsigned int get_size (void) const
   582    { return lenP1.static_size + (lenP1 ? lenP1 - 1 : 0) * Type::static_size; }
   583
   584    inline bool serialize (hb_serialize_context_t *c,
   585                           Supplier<Type> &items,
   586                           unsigned int items_len)
   587    {
   588      TRACE_SERIALIZE (this);
   589      if (unlikely (!c->extend_min (*this))) return_trace (false);
   590      lenP1.set (items_len); /* TODO(serialize) Overflow? */
   591      if (unlikely (!items_len)) return_trace (true);
   592      if (unlikely (!c->extend (*this))) return_trace (false);
   593      for (unsigned int i = 0; i < items_len - 1; i++)
   594        arrayZ[i] = items[i];
   595      items += items_len - 1;
   596      return_trace (true);
   597    }
