   600    {
   601      TRACE_SANITIZE (this);
   602      if (unlikely (!sanitize_shallow (c))) return_trace (false);
   603
   604      /* Note: for structs that do not reference other structs,
   605       * we do not need to call their sanitize() as we already did
   606       * a bound check on the aggregate array size.  We just include
   607       * a small unreachable expression to make sure the structs
   608       * pointed to do have a simple sanitize(), ie. they do not
   609       * reference other structs via offsets.
