    30  static void
    31  test_collect_unicodes_format4 (void)
    32  {
    33    hb_face_t *face = hb_subset_test_open_font("fonts/Roboto-Regular.abc.format4.ttf");
    34    hb_set_t *codepoints = hb_set_create();
    35
