    39    g_assert (hb_set_next (codepoints, &cp));
    40    g_assert_cmpuint (0x61, ==, cp);
    41    g_assert (hb_set_next (codepoints, &cp));
    42    g_assert_cmpuint (0x62, ==, cp);
    43    g_assert (hb_set_next (codepoints, &cp));
    44    g_assert_cmpuint (0x63, ==, cp);
    45    g_assert (!hb_set_next (codepoints, &cp));
    46
    47    hb_set_destroy (codepoints);
    48    hb_face_destroy (face);
    49  }
